import{_ as t,o as a,c as o,a4 as i}from"./chunks/framework.DCsBdTIw.js";const h=JSON.parse('{"title":"Models and Billing","description":"Tokeness prepaid billing model, model price authority, usage logs, and cost control guidance.","frontmatter":{"title":"Models and Billing","description":"Tokeness prepaid billing model, model price authority, usage logs, and cost control guidance."},"headers":[],"relativePath":"billing/pricing.md","filePath":"billing/pricing.md","lastUpdated":1783489381000}'),l={name:"billing/pricing.md"};function r(n,e,d,s,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="models-and-billing" tabindex="-1">Models and Billing <a class="header-anchor" href="#models-and-billing" aria-label="Permalink to &quot;Models and Billing&quot;">​</a></h1><p>Tokeness uses a prepaid billing model. Requests are deducted by actual usage according to the current model price policy.</p><h2 id="price-authority" tabindex="-1">Price Authority <a class="header-anchor" href="#price-authority" aria-label="Permalink to &quot;Price Authority&quot;">​</a></h2><p>Current model prices are authoritative in the Tokeness console model marketplace or in a formal quotation. Documentation does not publish fixed price numbers because model availability and upstream costs can change.</p><h2 id="cost-control" tabindex="-1">Cost Control <a class="header-anchor" href="#cost-control" aria-label="Permalink to &quot;Cost Control&quot;">​</a></h2><ul><li>Use separate API keys for different projects.</li><li>Set quota limits for prototypes and shared tools.</li><li>Review usage logs after integration tests.</li><li>Copy model names from the marketplace to avoid routing errors.</li></ul><h2 id="billing-checklist" tabindex="-1">Billing Checklist <a class="header-anchor" href="#billing-checklist" aria-label="Permalink to &quot;Billing Checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Insufficient balance</td><td>Account balance and key quota.</td></tr><tr><td>Unexpected cost</td><td>Usage logs, model name, and request volume.</td></tr><tr><td>Model not available</td><td>Current model marketplace and key group settings.</td></tr><tr><td>Tool retries too often</td><td>Client retry configuration and error logs.</td></tr></tbody></table>',8)])])}const m=t(l,[["render",r]]);export{h as __pageData,m as default};
